import{_ as e,o,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Fechar janelas de documentos","description":"","frontmatter":{"title":"Fechar janelas de documentos","id":"eproc-fechar-janelas-documentos","plataforma":"eproc","grupo":"Menu superior","plano":"free","desde":"1.10.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-fechar-janelas-documentos.md","filePath":"funcionalidades/eproc-fechar-janelas-documentos.md"}'),n={name:"funcionalidades/eproc-fechar-janelas-documentos.md"};function c(d,a,t,l,i,u){return o(),s("div",null,a[0]||(a[0]=[r('<h1 id="fechar-janelas-de-documentos" tabindex="-1">Fechar janelas de documentos <a class="header-anchor" href="#fechar-janelas-de-documentos" aria-label="Permalink to &quot;Fechar janelas de documentos&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>O eproc fecha sozinho as janelas de documentos quando você fecha o processo. Este recurso põe um botão ao lado do número do processo que faz o mesmo a qualquer momento: fecha de uma vez as janelas de documentos abertas, e o processo continua aberto.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo, ao lado do número do processo.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra alguns documentos pela tabela de eventos. Ao lado do número do processo aparece um ícone de janela com um &quot;x&quot; e, com mais de uma janela aberta, a quantidade.</li><li>Clique no ícone. As janelas de documentos se fecham, e o ícone some.</li></ol><p>Se você fechar alguma janela à mão, a quantidade diminui sozinha.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Valem só as janelas de documentos abertas a partir da página do processo que está na tela.</li><li>Se a página do processo for recarregada, as janelas abertas antes disso não entram na contagem e não são fechadas pelo botão.</li><li>Outras janelas, como a de minutas, não são fechadas.</li></ul>',12)]))}const h=e(n,[["render",c]]);export{m as __pageData,h as default};
